const visual = {
  prepare: function (input) { return []; },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cols = 4;
    var rows = 6;
    var margin = 24;
    var cell = Math.min((W - 2 * margin) / cols, (H - 2 * margin) / rows);
    var gw = cols * cell;
    var gh = rows * cell;
    var x0 = (W - gw) / 2;
    var y0 = (H - gh) / 2;
    var cmds = [];
    var i, j, seg;
    for (i = 0; i <= cols; i++) {
      var x = x0 + i * cell;
      seg = visualSdk.polyline([[x, y0], [x, y0 + gh]]);
      for (j = 0; j < seg.length; j++) { cmds.push(seg[j]); }
    }
    for (j = 0; j <= rows; j++) {
      var y = y0 + j * cell;
      seg = visualSdk.polyline([[x0, y], [x0 + gw, y]]);
      for (i = 0; i < seg.length; i++) { cmds.push(seg[i]); }
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid-4x6-24',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'grid', commands: cmds }],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'grid', stroke: '#26354a', strokeWidth: 1, fill: 'none' }
        ]
      }
    };
  },
};
